# pretool.sh gates a push in the repo it pushes (cd, -C, --git-dir), not the session's cwd (#30)
hook() { hook_json Bash "$1" "$2" | bash "$ORCA_SRC/hooks/pretool.sh" 2>/dev/null; echo $?; }
r=$(new_repo); d=$(dirname "$r")
git -C "$r" worktree add -q -b fresh "$d/fresh"; git -C "$r" worktree add -q -b stale "$d/stale"; git -C "$r" worktree add -q -b spaced "$d/fresh wt"
for w in "$r" "$d/fresh" "$d/stale" "$d/fresh wt"; do (cd "$w" && orca-lc gate >/dev/null); done
echo edit >> "$r/README"; echo edit >> "$d/stale/README"   # main checkout and stale: marker no longer matches
plain=$(mktemp -d); git init -q "$plain/p"                 # a repo without .orca/config.json

assert_eq "$(hook "$r" 'git push')" 2 "plain push from a stale cwd"
assert_eq "$(hook "$r" $'cat > notes <<EOF\ngit push origin main\nEOF' | tail -1)" 2 "a heredoc body line is gated, as on main"
assert_eq "$(hook "$r" $'cat > notes <<EOF\nEOF\ngit push' | tail -1)" 2 "a push after the heredoc terminator is gated"
assert_eq "$(hook "$r" $'n=$((1<<3))\ngit push origin main' | tail -1)" 2 "arithmetic << is no heredoc: the push after it is gated"
assert_eq "$(hook "$r" $'((x<<=2))\ngit push' | tail -1)" 2 "(( << )) is no heredoc either"
assert_eq "$(hook "$r" $'echo $[x<<y]\ngit push origin main' | tail -1)" 2 "\$[ << ] arithmetic is no heredoc"
assert_eq "$(hook "$r" $'git status # see <<EOF\ngit push origin main' | tail -1)" 2 "<< in a comment is no heredoc"
assert_eq "$(hook "$r" $'ls # a<<b\ngit push' | tail -1)" 2 "<< in a comment after a word is no heredoc"
assert_eq "$(hook "$r" $'# don\'t forget\ngit push' | tail -1)" 2 "a quote in a comment opens nothing"
assert_eq "$(hook "$r" 'echo a#b; git push' | tail -1)" 2 "# inside a word is no comment"
assert_eq "$(hook "$r" 'echo ${x:- #y}; git push' | tail -1)" 2 "# after a space inside \${ } is no comment"
assert_eq "$(hook "$r" 'echo ${x/ #/}; git push' | tail -1)" 2 "# in a \${ } pattern is no comment"
assert_eq "$(hook "$r" 'a=${b:-x #}; git push' | tail -1)" 2 "# in an assignment's \${ } is no comment"
assert_eq "$(hook "$r" 'echo `echo #`; git push' | tail -1)" 2 "# inside backticks is no comment"
assert_eq "$(hook "$r" $'echo $[ 1 # ]\n>out git push' | tail -1)" 2 "# inside \$[ ] is no comment"
assert_eq "$(hook "$r" $'echo $[(1+(2))]; ((x<<y))\ngit push' | tail -1)" 2 ")) inside \$[ ] leaves the (( )) count alone"
# no heredoc or comment hides a push (#9 review round 2)
assert_eq "$(hook "$r" $'echo ${x/<<EOF/}\ngit push' | tail -1)" 2 "<< inside \${ } hides nothing"
assert_eq "$(hook "$r" $'echo `echo <<EOF`\ngit push' | tail -1)" 2 "<< inside backticks hides nothing"
assert_eq "$(hook "$r" $'(( (1+(2)) <<x ))\ngit push' | tail -1)" 2 "inner )) does not close (( ))"
assert_eq "$(hook "$r" $'echo $(( (1+(2)) <<x ))\ngit push' | tail -1)" 2 "inner )) does not close \$(( ))"
assert_eq "$(hook "$r" $'(( (1+(2)) <<x ))\ngit push\nx' | tail -1)" 2 "a shift with a matching later line is still no heredoc"
assert_eq "$(hook "$r" 'echo ${x:-$(echo }) #}; git push' | tail -1)" 2 "} in \$( ) inside \${ } hides nothing"
assert_eq "$(hook "$r" 'echo ${x:-`echo }` #}; git push' | tail -1)" 2 "} in backticks inside \${ } hides nothing"
assert_eq "$(hook "$r" $'echo $(cat <<EOF\nhi\nEOF)\ngit push' | tail -1)" 2 "heredoc in \$( ) ending on EOF) hides nothing"
assert_eq "$(hook "$r" $'echo `cat <<EOF\nhi\nEOF`\ngit push' | tail -1)" 2 "heredoc in backticks ending on EOF\` hides nothing"
assert_eq "$(hook "$r" $'((cd .) ) # it\'s\ngit push' | tail -1)" 2 "an apostrophe after an unclosed (( hides nothing"
assert_eq "$(hook "$r" $'cat > notes <<EOF\ngit push origin main' | tail -1)" 2 "an unterminated heredoc hides nothing"
assert_eq "$(hook "$r" $'echo $(cat <<EOF\nit\'s\nEOF)\ngit push' | tail -1)" 2 "a quote in a heredoc body in \$( ) hides nothing"
assert_eq "$(hook "$r" $'echo `cat <<EOF\na"b\nEOF`\ngit push' | tail -1)" 2 "a quote in a heredoc body in backticks hides nothing"
assert_eq "$(hook "$r" $'echo "$(echo "it\'s")"\ngit push' | tail -1)" 2 "a quote nested in \"\$( )\" hides nothing"
# a # glued to a ) is no comment; any word after << is a heredoc delimiter (#9 review round 3)
assert_eq "$(hook "$r" 'echo $(echo a)#b; git push' | tail -1)" 2 "# after \$( ) is no comment"
assert_eq "$(hook "$r" 'echo $((1))#b; git push' | tail -1)" 2 "# after \$(( )) is no comment"
assert_eq "$(hook "$r" 'echo $(echo a)#b && git push' | tail -1)" 2 "# after \$( ) before && is no comment"
assert_eq "$(hook "$r" 'cat <(echo a)#b; git push' | tail -1)" 2 "# after <( ) is no comment"
assert_eq "$(hook "$r" 'cat >(cat)#b; git push' | tail -1)" 2 "# after >( ) is no comment"
assert_eq "$(hook "$r" '[[ a =~ (a)#b ]]; git push' | tail -1)" 2 "# after =~ ( ) is no comment"
assert_eq "$(hook "$r" $'cat << -EOF\nx <<Y\n-EOF\ngit push\nY' | tail -1)" 2 "-EOF is a heredoc delimiter"
assert_eq "$(hook "$r" $'cat <<1\nx <<Y\n1\ngit push\nY' | tail -1)" 2 "1 is a heredoc delimiter"
assert_eq "$(hook "$r" $'cat <<$x\nx <<Y\n$x\ngit push\nY' | tail -1)" 2 "\$x is a heredoc delimiter"
assert_eq "$(hook "$r" $'cat <<1\ngit push\n1' | tail -1)" 2 "a body line after <<1 is gated, as on main"
# cd carries through an ambiguous parse: no false block (#9 review round 3)
assert_eq "$(hook "$r" $'cd ../fresh\necho ${x/ #/}\ngit push' | tail -1)" 0 "cd carries through an ambiguous parse"
assert_eq "$(hook "$r" $'cd ../fresh && x=$(cat <<EOF\nhi\nEOF\n)\ngit push' | tail -1)" 0 "cd carries past a heredoc in \$( )"
assert_eq "$(hook "$r" $'cd ../fresh\necho ${x/ #/}\ncd ../stale\ngit push' | tail -1)" 2 "a later cd to a stale tree still gates"
assert_eq "$(hook "$r" $'cat <<EOF\ncd ../fresh\nEOF\necho ${x/ #/}\ngit push' | tail -1)" 2 "a cd in a heredoc body moves no push in the fallback"
assert_eq "$(hook "$r" $'cat <<EOF\ncd ../fresh\nEOF\necho $(echo a)#b; git push' | tail -1)" 2 "a cd in a heredoc body moves no push after # after )"
# << where bash reads no heredoc or another delimiter; # mid-word after a dup or inside [[ ]] (#9 review round 4)
assert_eq "$(hook "$r" $'a[1<<2]=3\ngit push\n2]=3' | tail -1)" 2 "<< in an array subscript is no heredoc"
assert_eq "$(hook "$r" $'[[ a =~ (<<E) ]]\ngit push\nE' | tail -1)" 2 "<< in a [[ =~ ]] group is no heredoc"
assert_eq "$(hook "$r" $'cat <<$\'E\'\nhi\nE\ngit push\n$E' | tail -1)" 2 "<<\$'E' ends on E"
assert_eq "$(hook "$r" $'cat <<$"E"\nhi\nE\ngit push\n$E' | tail -1)" 2 "<<\$\"E\" ends on E"
assert_eq "$(hook "$r" $'cat <<$\'E\'\ngit push\nE' | tail -1)" 2 "a body line after <<\$'E' is gated, as on main"
assert_eq "$(hook "$r" $'echo ${x:-<<EOF}\ngit push\nEOF}' | tail -1)" 2 "<< whose word closes \${ } hides nothing"
assert_eq "$(hook "$r" $'echo `echo <<EOF`\ngit push\nEOF`' | tail -1)" 2 "<< whose word closes a backtick hides nothing"
assert_eq "$(hook "$r" 'cat <&0#b; git push' | tail -1)" 2 "# after <&0 is no comment"
assert_eq "$(hook "$r" 'cat <&$x#b; git push' | tail -1)" 2 "# after <&\$x is no comment"
assert_eq "$(hook "$r" 'cat 0<&0#b; git push' | tail -1)" 2 "# after 0<&0 is no comment"
assert_eq "$(hook "$r" '[[ a =~ (#) ]]; git push' | tail -1)" 2 "# in a [[ =~ ]] group is no comment"
assert_eq "$(hook "$r" '[[ a =~ ( #) ]]; git push' | tail -1)" 2 "# after a blank in [[ =~ ( ) ]] is no comment"
assert_eq "$(hook "$r" '[[ a == @(#|a) ]]; git push' | tail -1)" 2 "# in an @( ) extglob is no comment"
assert_eq "$(hook "$r" '[[ a == !(#) ]]; git push' | tail -1)" 2 "# in a !( ) extglob is no comment"
# [[ after a keyword (#9 round-5 verify)
assert_eq "$(hook "$r" 'if true; then [[ a =~ ( #) ]]; git push; fi' | tail -1)" 2 "# in [[ ]] after then is no comment"
assert_eq "$(hook "$r" '! [[ a =~ ( #) ]]; git push' | tail -1)" 2 "# in [[ ]] after ! is no comment"
assert_eq "$(hook "$r" 'time [[ a =~ ( #) ]]; git push' | tail -1)" 2 "# in [[ ]] after time is no comment"
assert_eq "$(hook "$r" '{ [[ a =~ ( #) ]]; }; git push' | tail -1)" 2 "# in [[ ]] after { is no comment"
assert_eq "$(hook "$r" 'if [[ a == !( #) ]]; then :; fi; git push' | tail -1)" 2 "# in [[ ]] after if is no comment"
assert_eq "$(hook "$r" $'if [[ a =~ (<<E) ]]; then :; fi\ngit push\nE' | tail -1)" 2 "<< in [[ ]] after if is no heredoc"
assert_eq "$(hook "$r" $'while [[ a =~ (<<E) ]]; do break; done\ngit push\nE' | tail -1)" 2 "<< in [[ ]] after while is no heredoc"
assert_eq "$(hook "$r" $'! [[ a =~ (<<E) ]]\ngit push\nE' | tail -1)" 2 "<< in [[ ]] after ! is no heredoc"
assert_eq "$(hook "$r" $'time [[ a =~ (<<E) ]]\ngit push\nE' | tail -1)" 2 "<< in [[ ]] after time is no heredoc"
assert_eq "$(hook "$r" $'{ [[ a =~ (<<E) ]]; }\ngit push\nE' | tail -1)" 2 "<< in [[ ]] after { is no heredoc"
# nested quotes in dquotes, two dollars or an escaped backslash before a quote, ]] in a [[ ( ) group (#9 review round 5)
assert_eq "$(hook "$r" 'printf "%s\n" "$(git log --format="%s #%h" -1)"; git push' | tail -1)" 2 "a dquote in a command substitution inside dquotes hides no comment"
assert_eq "$(hook "$r" 'echo "$(echo " #")"; git push' | tail -1)" 2 "# quoted inside a command substitution in dquotes is no comment"
assert_eq "$(hook "$r" 'echo "${x:-" #"}"; git push' | tail -1)" 2 "# quoted inside a parameter expansion in dquotes is no comment"
assert_eq "$(hook "$r" 'echo "`echo " #"`"; git push' | tail -1)" 2 "# quoted inside a backtick in dquotes is no comment"
assert_eq "$(hook "$r" $'echo "${x:-" <<E"}"\ngit push\nE}' | tail -1)" 2 "<< quoted inside a parameter expansion in dquotes is no heredoc"
assert_eq "$(hook "$r" $'echo $$\'it\\\'; git push; #\'' | tail -1)" 2 "two dollars then a quote: the PID and a plain quote"
assert_eq "$(hook "$r" $'echo $$\'\\\'; git push #\'' | tail -1)" 2 "two dollars then a quoted backslash ends at the second quote"
assert_eq "$(hook "$r" $'echo \\\\$\'a\\\'b\'; git push' | tail -1)" 2 "an escaped backslash then a dollar quote is ANSI-C quoting"
assert_eq "$(hook "$r" '[[ a =~ ( ]] #) ]]; git push' | tail -1)" 2 "]] in a [[ ( ) group ends nothing"
assert_eq "$(hook "$r" '[[ a == @( ]] #|a) ]]; git push' | tail -1)" 2 "]] in an @( ) extglob ends nothing"
assert_eq "$(hook "$r" $'[[ a =~ ( ]] <<E) ]]\ngit push\nE' | tail -1)" 2 "]] in a [[ ( ) group leaves << no heredoc"
# a substitution in dquotes holding what the tokenizer does not model (#9 round-6 verify)
assert_eq "$(hook "$r" 'echo "$(echo \) " #")"; git push' | tail -1)" 2 "an escaped paren in a command substitution in dquotes hides nothing"
assert_eq "$(hook "$r" $'echo "$(echo \')\' " #")"; git push' | tail -1)" 2 "a quoted paren in a command substitution in dquotes hides nothing"
assert_eq "$(hook "$r" 'echo "$(case a in a) echo " #";; esac)"; git push' | tail -1)" 2 "a case pattern in a command substitution in dquotes hides nothing"
assert_eq "$(hook "$r" $'echo "${x:-\'}\' " #"}"; git push' | tail -1)" 2 "a quoted brace in a parameter expansion in dquotes hides nothing"
assert_eq "$(hook "$r" $'echo "$(echo a # ) " #\n)"; git push' | tail -1)" 2 "a comment in a command substitution in dquotes hides nothing"
assert_eq "$(hook "$r" 'echo "`echo \` " #`"; git push' | tail -1)" 2 "an escaped backtick in a backtick in dquotes hides nothing"
assert_eq "$(hook "$r" 'echo "$(echo } " #")"; git push' | tail -1)" 2 "a bare brace in a command substitution in dquotes hides nothing"
assert_eq "$(hook "$r" 'echo "$(echo a}b " #")"; git push' | tail -1)" 2 "a brace mid-word in a command substitution in dquotes hides nothing"
assert_eq "$(hook "$r" 'echo "${x:-$(echo }) " #"}"; git push' | tail -1)" 2 "a brace in a command substitution in a parameter expansion in dquotes hides nothing"
assert_eq "$(hook "$r" 'echo "$(echo ${x%)} " #")"; git push' | tail -1)" 2 "a paren in a nested parameter pattern in dquotes hides nothing"
assert_eq "$(hook "$r" 'echo "$(echo ${x/)/} " #")"; git push' | tail -1)" 2 "a paren in a nested substitution pattern in dquotes hides nothing"
assert_eq "$(hook "$r" 'echo "${x:-`echo }` " #"}"; git push' | tail -1)" 2 "a brace in a backtick in a parameter expansion in dquotes hides nothing"
assert_eq "$(hook "$r" 'echo "$(echo `echo )` " #")"; git push' | tail -1)" 2 "a paren in a backtick in a command substitution in dquotes hides nothing"
assert_eq "$(hook "$r" 'echo "$(echo `date`) b" # git push' | tail -1)" 0 "a backtick in a dquoted command substitution leaves a later comment a comment"
assert_eq "$(hook "$r" $'echo "$( (true)# ) " <<\'E)"\'\ngit push\nE)"' | tail -1)" 2 "a comment after a paren in a command substitution in dquotes hides nothing"
assert_eq "$(hook "$r" 'echo "$(echo ${#x} a#b) " # git push' | tail -1)" 0 "a # inside a word in a dquoted command substitution leaves a later comment a comment"
assert_eq "$(hook "$r" $'git commit -m "$(cat <<\'EOF\'\nit\'s "x" (1) fix)\ngit push later\nEOF\n)"' | tail -1)" 0 "a heredoc body in a dquoted command substitution stays skipped"
# << in arithmetic inside "..", a heredoc ending on E) or E` in "..", a delimiter word opening a substitution (#9 review round 6)
assert_eq "$(hook "$r" $'echo "$((1<<x))\n"\ngit push\nx\n"' | tail -1)" 2 "<< in \$(( )) in dquotes hides nothing"
assert_eq "$(hook "$r" $'echo "$( ((x<<y))\n)"\ngit push\ny\n)"' | tail -1)" 2 "<< in (( )) in a command substitution in dquotes hides nothing"
assert_eq "$(hook "$r" $'echo "$(echo $((1<<y)))\n"\ngit push\ny\n"' | tail -1)" 2 "<< in \$(( )) in a command substitution in dquotes hides nothing"
assert_eq "$(hook "$r" $'echo "$((1<<2))\n"; git push\n2\n#"' | tail -1)" 2 "a numeric shift operand in dquotes is no heredoc word"
assert_eq "$(hook "$r" $'x="${y:-$((1<<E))}\n"; git push\nE\n#"' | tail -1)" 2 "<< in \$(( )) in a parameter expansion in dquotes hides nothing"
assert_eq "$(hook "$r" $'echo "$(cat <<E\nhi\nE)"; git push; cat <<\'X\'\nE\n)"\nX' | tail -1)" 2 "a heredoc in a command substitution in dquotes ends on E)"
assert_eq "$(hook "$r" $'echo "`cat <<E\nhi\nE`"; git push; cat <<\'X\'\nE\n`"\nX' | tail -1)" 2 "a heredoc in a backtick in dquotes ends on E\`"
assert_eq "$(hook "$r" $'cat <<$(echo E)\nbody\n$(echo E)\ngit push\n$' | tail -1)" 2 "a delimiter word opening \$( ) hides nothing"
assert_eq "$(hook "$r" $'cat <<${x:- y}\nbody\n${x:- y}\ngit push\n${x:-' | tail -1)" 2 "a delimiter word opening \${ } hides nothing"
assert_eq "$(hook "$r" $'cat <<`echo E`\nb\n`echo E`\ngit push\n`echo' | tail -1)" 2 "a delimiter word opening a backtick hides nothing"
assert_eq "$(hook "$r" "[[ a < b ]] && echo 'ok; git push later'" | tail -1)" 0 "< in [[ ]] leaves a quoted push text alone"
assert_eq "$(hook "$r" 'git pu"sh" origin main' | tail -1)" 2 "a verb split by quotes is still read by main's reading"
assert_eq "$(hook "$r" 'git p\ush' | tail -1)" 2 "a verb split by a backslash is still read by main's reading"
# a push origin/main's reading misses: a redirect glued to the verb
assert_eq "$(hook "$r" 'git push>/dev/null' | tail -1)" 2 "a push with a glued > redirect is gated"
assert_eq "$(hook "$r" 'git push<<<y' | tail -1)" 2 "a push with a glued here-string is gated"
assert_eq "$(hook "$d/fresh" 'git push origin HEAD')" 0 "plain push from a fresh cwd"
assert_eq "$(hook "$r" "cd $d/fresh && git push")" 0 "cd <fresh> && git push from a stale cwd"
assert_eq "$(hook "$r" 'cd ../fresh && git push')" 0 "relative cd resolves against the payload cwd"
assert_eq "$(hook "$d/fresh" "git -C $d/stale push")" 2 "git -C <stale> push from a fresh cwd"
assert_eq "$(hook "$r" 'git -C ../fresh push')" 0 "relative -C"
assert_eq "$(hook "$r" "git -C \"$d/fresh wt\" push")" 0 "quoted -C path with a space"
assert_eq "$(hook "$r" "cd '$d/fresh wt' && git push")" 0 "quoted cd path with a space"
assert_eq "$(hook "$d/fresh" 'git -c push.default=current push')" 0 "git -c k=v push, fresh"
assert_eq "$(hook "$d/fresh" "echo hi; git -c k=v -C $d/stale push origin HEAD")" 2 "-c and -C after ; in a chain"
assert_eq "$(hook "$d/fresh" "true && cd $d/stale && git push 2>&1 | tail -1")" 2 "cd mid-chain, piped push"
assert_eq "$(hook "$d/fresh" "git --git-dir=$r/.git push")" 2 "--git-dir= of the stale main checkout"
assert_eq "$(hook "$r" "git --git-dir $r/.git/worktrees/fresh push")" 0 "--git-dir <linked worktree gitdir>"
assert_eq "$(hook "$d/fresh" "git -C $d/fresh push && git -C $d/stale push")" 2 "every push in the chain is judged"
assert_eq "$(hook "$d/fresh" "bash -c 'cd $d/stale && git push'")" 2 "bash -c is read as a command"
assert_eq "$(hook "$plain" "git -C $d/stale push")" 2 "non-Orca cwd pushing into an Orca repo is gated"
assert_eq "$(hook "$r" "git -C $plain/p push")" 0 "push into a repo without config is left alone"
assert_eq "$(hook "$r" "git -C $d/stale status")" 0 "not a push"
assert_eq "$(hook "$r" 'echo git push')" 0 "git push as an argument is not a push"
assert_contains "$(hook_json Bash "$d/fresh" "git -C $d/stale push" | bash "$ORCA_SRC/hooks/pretool.sh" 2>&1)" "stale for $d/stale"
assert_eq "$(hook "$d/fresh" 'git merge stale')" 2 "merge still blocked"
